<div x-data="lpjuShow({{ $id }})" x-init="init()" x-cloak><div class="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="text-sm text-slate-600">Informasi lengkap aset</p><h2 class="mt-1 text-2xl font-semibold tracking-tight text-navy-900">Detail <span x-text="item ? code(item) : 'LPJU'">LPJU</span></h2></div><div class="flex gap-2"><a href="{{ route('assets.lpju.index') }}" class="action-button">Kembali</a><a href="{{ route('assets.lpju.edit', $id) }}" class="action-button-primary">Edit</a></div></div><div x-show="error" role="alert" class="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700" x-text="error"></div><div x-show="loading" class="rounded-2xl border border-border bg-white p-8 text-sm text-slate-500">Memuat detail...</div><div x-show="item && !loading" class="grid gap-5 lg:grid-cols-[minmax(0,1fr)_340px]"><section class="rounded-2xl border border-border bg-white p-6 shadow-sm"><div class="grid gap-5 sm:grid-cols-2"><div><p class="detail-label">Alamat</p><p class="detail-value" x-text="item?.alamat || '-'"></p></div><div><p class="detail-label">Status</p><span class="inline-flex rounded-full px-2.5 py-1 text-xs font-medium" :class="statusClass(item?.status)" x-text="item?.status || '-' "></span></div><div><p class="detail-label">Desa / Kecamatan</p><p class="detail-value" x-text="`${item?.desa?.desa || '-'} / ${item?.desa?.kecamatan?.kecamatan || item?.desa?.kec_dtks || '-'}`"></p></div><div><p class="detail-label">Sumber dana</p><p class="detail-value" x-text="item?.sumber_dana?.nama_sumber || '-' "></p></div><div><p class="detail-label">Koordinat</p><p class="detail-value" x-text="`${item?.latitude || '-'}, ${item?.longitude || '-'}`"></p></div><div><p class="detail-label">Tahun anggaran</p><p class="detail-value" x-text="item?.tahun_anggaran || '-' "></p></div><div><p class="detail-label">Tanggal diterima</p><p class="detail-value" x-text="item?.tanggal_diterima || '-' "></p></div><div><p class="detail-label">Tanggal pasang</p><p class="detail-value" x-text="item?.tanggal_pasang || '-' "></p></div></div></section><aside class="rounded-2xl border border-border bg-white p-5 shadow-sm"><p class="detail-label">Foto aset</p><template x-if="item?.foto"><a :href="photoUrl(item.foto)" target="_blank" rel="noreferrer"><img :src="photoUrl(item.foto)" alt="Foto LPJU" class="mt-3 aspect-[4/3] w-full rounded-xl object-cover"></a></template><p x-show="!item?.foto" class="mt-3 rounded-xl bg-slate-50 p-8 text-center text-sm text-slate-500">Belum ada foto.</p><div class="mt-5"><p class="detail-label">Petugas</p><p class="detail-value" x-text="item?.petugas?.name || '-' "></p></div></aside></div><section x-show="item && !loading" class="mt-5 rounded-2xl border border-border bg-white p-6 shadow-sm"><h3 class="font-semibold text-navy-900">Histori perubahan</h3><div class="mt-4 space-y-3"><template x-for="history in (item?.histori || [])" :key="history.id"><div class="border-l-2 border-teal-400 pl-4 text-sm"><p class="font-medium text-slate-700" x-text="`${history.status_lama} → ${history.status_baru}`"></p><p class="text-xs text-slate-500" x-text="history.keterangan || history.tanggal || '-' "></p></div></template><p x-show="!item?.histori?.length" class="text-sm text-slate-500">Belum ada histori perubahan.</p></div></section></div>
<script>function lpjuShow(id){return{item:null,loading:true,error:'',async init(){try{this.item=(await window.axios.get(`/api/lpju/${id}`)).data;}catch(e){this.error=e.response?.data?.message||'Gagal memuat detail LPJU.';}finally{this.loading=false;}},code(x){return`LPJU-${String(x.id).padStart(4,'0')}`},statusClass(s){return s==='baik'?'bg-teal-100 text-teal-800':s==='rusak'?'bg-red-100 text-red-800':'bg-yellow-100 text-yellow-800'},photoUrl(p){return p?.startsWith('http')?p:`/storage/${p}`}}}</script>
